def _kvpr(w, mem):
    """KVPR = weighted req rate / free memory."""
    return w / (GPU_MEM_SIZE - mem) if mem < GPU_MEM_SIZE else float('inf')


def compute_model_placement(gpu_num, models):
    """
    Greedy placement (min resulting KVPR) followed by a local search that
    repeatedly moves or swaps models between GPUs whenever it strictly
    reduces the maximum KVPR across GPUs. Simple and fast.
    """
    sorted_models = sorted(models, key=lambda m: (m.req_rate / m.slo), reverse=True)

    placement = {gpu_id: [] for gpu_id in range(gpu_num)}
    shared_kv = [0.0 for _ in range(gpu_num)]
    weighted_req_rate = [0.0 for _ in range(gpu_num)]

    for model in sorted_models:
        best_idx = None
        best_key = (float('inf'), float('-inf'))
        for gpu_id in range(gpu_num):
            free = shared_kv[gpu_id] + model.model_size
            if free < GPU_MEM_SIZE:
                ratio = (weighted_req_rate[gpu_id] + model.req_rate / model.slo) / (GPU_MEM_SIZE - free)
                key = (ratio, -free)
                if key < best_key:
                    best_key = key
                    best_idx = gpu_id
        if best_idx is None:
            raise ValueError(f"Cannot place model of size {model.model_size} GB")
        placement[best_idx].append(model)
        weighted_req_rate[best_idx] += model.req_rate / model.slo
        shared_kv[best_idx] += model.model_size

    # Ejection-chain local search targeting the bottleneck (argmax-KVPR) GPU.
    # Each round: from the bottleneck GPU, try (1) single moves of a model to
    # another GPU, (2) pairwise swaps with other GPUs, and (3) depth-2 chains:
    # eject model i from the bottleneck to some GPU g2, then relocate one model
    # k from any GPU to the bottleneck or a third GPU. Accept the first
    # candidate that strictly lowers the global max KVPR; stop when none does.
    def apply_move(g_from, g_to, model):
        placement[g_from].remove(model)
        placement[g_to].append(model)
        r = model.req_rate / model.slo
        weighted_req_rate[g_from] -= r
        weighted_req_rate[g_to] += r
        shared_kv[g_from] -= model.model_size
        shared_kv[g_to] += model.model_size

    def fits(g, size):
        return shared_kv[g] + size < GPU_MEM_SIZE

    def global_max():
        return max(_kvpr(weighted_req_rate[g], shared_kv[g]) for g in range(gpu_num))

    improved = True
    while improved:
        improved = False
        cur = global_max()
        if cur == float('inf'):
            break
        bottleneck = max(range(gpu_num), key=lambda g: _kvpr(weighted_req_rate[g], shared_kv[g]))

        # (1) depth-1: single move off the bottleneck
        for model in list(placement[bottleneck]):
            for g2 in range(gpu_num):
                if g2 == bottleneck or not fits(g2, model.model_size):
                    continue
                apply_move(bottleneck, g2, model)
                nm = global_max()
                if nm < cur - 1e-12:
                    improved = True
                    break
                apply_move(g2, bottleneck, model)  # undo
            if improved:
                break
        if improved:
            continue

        # (2) depth-1: swap bottleneck model with another GPU's model
        for a in list(placement[bottleneck]):
            for g2 in range(gpu_num):
                if g2 == bottleneck:
                    continue
                for b in list(placement[g2]):
                    if (fits(bottleneck, b.model_size - a.model_size) and
                            fits(g2, a.model_size - b.model_size)):
                        apply_move(bottleneck, g2, a)
                        apply_move(g2, bottleneck, b)
                        nm = global_max()
                        if nm < cur - 1e-12:
                            improved = True
                            break
                        apply_move(bottleneck, g2, b)  # undo
                        apply_move(g2, bottleneck, a)
                if improved:
                    break
            if improved:
                break
        if improved:
            continue

        # (3) depth-2 ejection chains: move i off bottleneck to g2, then move
        # some model k from any GPU (incl. g2) to bottleneck or a third GPU.
        for a in list(placement[bottleneck]):
            for g2 in range(gpu_num):
                if g2 == bottleneck or not fits(g2, a.model_size):
                    continue
                apply_move(bottleneck, g2, a)
                # try moving some k onto the relieved bottleneck or elsewhere
                for g3 in range(gpu_num):
                    for k in list(placement[g3]):
                        if k is a:
                            continue
                        dest = bottleneck if g3 != bottleneck else g2
                        if g3 == dest or not fits(dest, k.model_size):
                            continue
                        apply_move(g3, dest, k)
                        nm = global_max()
                        if nm < cur - 1e-12:
                            improved = True
                            break
                        apply_move(dest, g3, k)  # undo
                    if improved:
                        break
                if improved:
                    break
                apply_move(g2, bottleneck, a)  # undo chain
                break_outer = improved
                if break_outer:
                    break
            if improved:
                break

    return placement

